DO $$ BEGIN RAISE EXCEPTION 'PROBE not due now: %', (SELECT count(*) || ' / $' || coalesce(sum(i.balance_due), 0) FROM invoices i JOIN jobs j ON j.id = i.job_id WHERE i.balance_due > 0.004 AND i.status NOT IN ('void','draft') AND j.completed_at IS NULL AND coalesce(j.status,'') NOT IN ('completed','cancelled') AND EXISTS (SELECT 1 FROM visits v WHERE v.job_id = j.id AND coalesce(v.status,'') NOT IN ('completed','cancelled') AND v.scheduled_date >= current_date)); END $$;
